Add-Type -AssemblyName Microsoft.VisualBasic
$id='';try{$id=(Get-Clipboard -Raw).Trim()}catch{};if($id -notmatch '^[a-p]{32}$'){$id=''}
$id=[Microsoft.VisualBasic.Interaction]::InputBox('Confirm or paste the extension ID:', 'YouTube Audio', $id)
if($id -notmatch '^[a-p]{32}$'){[System.Windows.Forms.MessageBox]::Show('Invalid extension ID.');exit 1}
if([System.Windows.Forms.MessageBox]::Show('Register the bundled Native Messaging host for this extension? yt-dlp will only be downloaded later with your consent.','YouTube Audio','YesNo','Question') -ne 'Yes'){exit}
$dir=Join-Path $env:LOCALAPPDATA 'YouTubeAudioBridge\host';New-Item -ItemType Directory -Force $dir|Out-Null;Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'host.ps1'),(Join-Path $PSScriptRoot 'host.cmd') -Destination $dir -Force
$manifest=Join-Path $dir 'com.youtube_audio.bridge.json';$j=@{name='com.youtube_audio.bridge';description='YouTube Audio local host';path=(Join-Path $dir 'host.cmd');type='stdio';allowed_origins=@("chrome-extension://$id/")}|ConvertTo-Json;[IO.File]::WriteAllText($manifest,$j,[Text.UTF8Encoding]::new($false));$key='HKCU:\Software\Google\Chrome\NativeMessagingHosts\com.youtube_audio.bridge';New-Item -Path $key -Force|Out-Null;Set-Item -Path $key -Value $manifest;if ([System.Windows.Forms.MessageBox]::Show('Host registered. Download the official yt-dlp now and verify its SHA-256? No other tools will be installed.', 'YouTube Audio', 'YesNo', 'Question') -eq 'Yes') { Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') -ArgumentList @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File', ('"'+(Join-Path $dir 'host.ps1')+'"'), '-Mode','install') -WindowStyle Hidden -Wait | Out-Null; $statusPath = Join-Path $env:LOCALAPPDATA 'YouTubeAudioBridge\install.json'; if (Test-Path -LiteralPath $statusPath) { $status = Get-Content -LiteralPath $statusPath -Raw -Encoding UTF8 | ConvertFrom-Json; if ($status.status -eq 'ready') { [System.Windows.Forms.MessageBox]::Show('yt-dlp is installed and verified. Return to the extension and check the connection.') | Out-Null } else { [System.Windows.Forms.MessageBox]::Show(('yt-dlp installation failed: ' + $status.message)) | Out-Null; exit 1 } } else { [System.Windows.Forms.MessageBox]::Show('yt-dlp verification did not complete. Check the connection and retry from the extension.') | Out-Null; exit 1 } } else { [System.Windows.Forms.MessageBox]::Show('Host registered. You can install yt-dlp later from the extension.') | Out-Null }
